@@ -290,6 +290,81 @@ module Support
     RUBY
   end

+  it 'does not move a subject above another subject' do
+    expect_offense(<<~RUBY)
+      RSpec.describe User do
+        let(:foo) { bar }
+        subject(:a) { first }
+        ^^^^^^^^^^^^^^^^^^^^^ Declare `subject` above any other `let` declarations.
+        subject(:b) { second }
+        ^^^^^^^^^^^^^^^^^^^^^^ Declare `subject` above any other `let` declarations.
+      end
+    RUBY
+
+    expect_correction(<<~RUBY)
+      RSpec.describe User do
+        subject(:a) { first }
+        subject(:b) { second }
+        let(:foo) { bar }
+      end
+    RUBY
+  end
+
+  it 'moves several subjects above a preceding hook, keeping their order' do
+    expect_offense(<<~RUBY)
+      RSpec.describe User do
+        before { prepare }
+        subject(:a) { first }
+        ^^^^^^^^^^^^^^^^^^^^^ Declare `subject` above any other `before` declarations.
+        subject(:b) { second }
+        ^^^^^^^^^^^^^^^^^^^^^^ Declare `subject` above any other `before` declarations.
+        subject(:c) { third }
+        ^^^^^^^^^^^^^^^^^^^^^ Declare `subject` above any other `before` declarations.
+      end
+    RUBY
+
+    expect_correction(<<~RUBY)
+      RSpec.describe User do
+        subject(:a) { first }
+        subject(:b) { second }
+        subject(:c) { third }
+        before { prepare }
+      end
+    RUBY
+  end
+
+  it 'keeps the order of subjects separated by a let' do
+    expect_offense(<<~RUBY)
+      RSpec.describe User do
+        let(:x) { 1 }
+        subject(:a) { first }
+        ^^^^^^^^^^^^^^^^^^^^^ Declare `subject` above any other `let` declarations.
+        let(:y) { 2 }
+        subject(:b) { second }
+        ^^^^^^^^^^^^^^^^^^^^^^ Declare `subject` above any other `let` declarations.
+      end
+    RUBY
+
+    expect_correction(<<~RUBY)
+      RSpec.describe User do
+        subject(:a) { first }
+        subject(:b) { second }
+        let(:x) { 1 }
+        let(:y) { 2 }
+      end
+    RUBY
+  end
+
+  it 'does not register an offense for consecutive leading subjects' do
+    expect_no_offenses(<<~RUBY)
+      RSpec.describe User do
+        subject(:a) { first }
+        subject(:b) { second }
+        let(:foo) { bar }
+      end
+    RUBY
+  end
+
